using DotLLM.Cpu.Kernels;
using Xunit;

namespace DotLLM.Tests.Unit.Models.Qwen4Exp;

/// <summary>
/// Per-op parity of the Qwen4-Exp gated residual (#816) against HF <c>Qwen4ExpTextGatedResidual</c> (fixture generated by
/// <c>Reference/gen_gated_residual.py</c>) plus SIMD-vs-scalar and chunking invariants. Shapes are deliberately awkward
/// (H=48, lowRank=20, T=5, S=4, per-stream magnitude spread ~30x) so sum-vs-mean, wrong-axis and broadcast bugs fail.
/// </summary>
public sealed unsafe class Qwen4ExpGatedResidualTests
{
    private const float Tol = 2e-5f;
    private static readonly Qwen4ExpReferenceFixture Fx = Qwen4ExpReferenceFixture.Load("gated_residual.json");
    private readonly int _s = Fx.Int("hc_count"), _h = Fx.Int("hidden_size"), _r = Fx.Int("lowrank"), _t = Fx.Int("seq_len");
    private readonly float _eps = (float)Fx.Meta.GetProperty("eps").GetDouble();

    private static void AssertClose(float[] expected, float[] actual, string what, float tol = Tol)
    {
        Assert.Equal(expected.Length, actual.Length);
        float worst = 0; int at = 0;
        for (int i = 0; i < expected.Length; i++)
        {
            float d = MathF.Abs(expected[i] - actual[i]) / (1f + MathF.Abs(expected[i]));
            if (d > worst) { worst = d; at = i; }
        }
        Assert.True(worst <= tol, $"{what}: worst rel diff {worst:E3} at {at} (expected {expected[at]}, got {actual[at]})");
    }

    private static void Gemv(float[] weight, float[] x, float[] y, int m, int k, int n)
    {
        fixed (float* w = weight) fixed (float* xp = x) fixed (float* yp = y)
            MatMul.GemmF32(w, xp, yp, m, k, n);
    }

    [Theory]
    [InlineData("gr")]
    [InlineData("head")]
    public void GroupRmsNorm_MatchesHf_AndScalar(string tag)
    {
        var res = Fx.F32($"{tag}.residual");
        var gamma = Fx.F32($"{tag}.gamma");
        var got = new float[res.Length];
        Qwen4ExpGatedResidual.GroupRmsNorm(res, gamma, _s, _h, _eps, got, _t);
        AssertClose(Fx.F32($"{tag}.normed"), got, "GroupRmsNorm vs HF");

        var scalar = new float[res.Length];
        Qwen4ExpGatedResidual.GroupRmsNormScalar(res, gamma, _s, _h, _eps, scalar, _t);
        AssertClose(scalar, got, "GroupRmsNorm vs scalar", 1e-6f);

        // Per-stream gamma and per-stream RMS: a shared-gamma or whole-row-RMS impl cannot match.
        var shared = new float[res.Length];
        for (int t = 0; t < _t; t++)
            RmsNorm.Execute(res.AsSpan(t * _s * _h, _s * _h), gamma, _eps, shared.AsSpan(t * _s * _h, _s * _h));
        Assert.True(Math.Abs(shared[0] - got[0]) > 1e-3f || Math.Abs(shared[_h * 3] - got[_h * 3]) > 1e-3f,
            "fixture is not discriminating: whole-row RMS would also pass");
    }

    [Theory]
    [InlineData("gr")]
    [InlineData("head")]
    public void ReadPath_MatchesHf(string tag)
    {
        var normed = Fx.F32($"{tag}.normed");
        var down = Fx.F32($"{tag}.down");   // [R, S*H]
        var up = Fx.F32($"{tag}.up");       // [S*H, R]

        var d = new float[_t * _r];
        Gemv(down, normed, d, _r, _s * _h, _t);
        Qwen4ExpGatedResidual.ActivateLowRank(d, _s);
        AssertClose(Fx.F32($"{tag}.down_act"), d, "ActivateLowRank vs HF");

        var upOut = new float[_t * _s * _h];
        Gemv(up, d, upOut, _s * _h, _r, _t);
        var scratch = (float[])upOut.Clone();
        var h = new float[_t * _h];
        Qwen4ExpGatedResidual.MixAndMean(scratch, normed, _s, _h, h, _t);
        AssertClose(Fx.F32($"{tag}.mixed"), h, "MixAndMean vs HF");

        var hScalar = new float[_t * _h];
        Qwen4ExpGatedResidual.MixAndMeanScalar(upOut, normed, _s, _h, hScalar, _t);
        AssertClose(hScalar, h, "MixAndMean vs scalar", 1e-5f);
    }

    [Fact]
    public void InjectGains_MatchHf_AndScalar_AndVaryPerStream()
    {
        var normed = Fx.F32("gr.normed");
        var inject = Fx.F32("gr.inject");   // [S, S*H]
        var g = new float[_t * _s];
        Gemv(inject, normed, g, _s, _s * _h, _t);
        var gScalar = (float[])g.Clone();
        Qwen4ExpGatedResidual.InjectGains(g, _s);
        Qwen4ExpGatedResidual.InjectGainsScalar(gScalar, _s);
        AssertClose(Fx.F32("gr.gains"), g, "InjectGains vs HF");
        AssertClose(gScalar, g, "InjectGains vs scalar", 1e-6f);

        // Discrimination: gains differ across streams and tokens (a broadcast of g[t,0] / g[0,s] would not match).
        Assert.True(Math.Abs(g[0] - g[1]) > 1e-3f && Math.Abs(g[0] - g[_s]) > 1e-3f);
    }

    [Fact]
    public void Write_MatchesHf_AndScalar()
    {
        var res = Fx.F32("gr.residual");
        var y = Fx.F32("gr.block_out");
        var gains = Fx.F32("gr.gains");

        var got = (float[])res.Clone();
        Qwen4ExpGatedResidual.Write(got, y, gains, _s, _h, _t);
        AssertClose(Fx.F32("gr.new_residual"), got, "Write vs HF");

        var scalar = (float[])res.Clone();
        Qwen4ExpGatedResidual.WriteScalar(scalar, y, gains, _s, _h, _t);
        AssertClose(scalar, got, "Write vs scalar", 1e-6f);
    }

    [Fact]
    public void FullReadWrite_EndToEnd_MatchesHf()
    {
        var res = Fx.F32("gr.residual");
        var normed = new float[res.Length];
        Qwen4ExpGatedResidual.GroupRmsNorm(res, Fx.F32("gr.gamma"), _s, _h, _eps, normed, _t);
        var d = new float[_t * _r];
        Gemv(Fx.F32("gr.down"), normed, d, _r, _s * _h, _t);
        Qwen4ExpGatedResidual.ActivateLowRank(d, _s);
        var up = new float[res.Length];
        Gemv(Fx.F32("gr.up"), d, up, _s * _h, _r, _t);
        var h = new float[_t * _h];
        Qwen4ExpGatedResidual.MixAndMean(up, normed, _s, _h, h, _t);
        var g = new float[_t * _s];
        Gemv(Fx.F32("gr.inject"), normed, g, _s, _s * _h, _t);
        Qwen4ExpGatedResidual.InjectGains(g, _s);
        AssertClose(Fx.F32("gr.mixed"), h, "block input");

        var r2 = (float[])res.Clone();
        Qwen4ExpGatedResidual.Write(r2, Fx.F32("gr.block_out"), g, _s, _h, _t);
        AssertClose(Fx.F32("gr.new_residual"), r2, "new residual");
    }

    [Fact]
    public void Chunked_EqualsSingleShot()
    {
        // GR is stateless per token: processing tokens [0,2) then [2,T) must equal one call.
        var res = Fx.F32("gr.residual");
        var gamma = Fx.F32("gr.gamma");
        var whole = new float[res.Length];
        Qwen4ExpGatedResidual.GroupRmsNorm(res, gamma, _s, _h, _eps, whole, _t);
        var chunked = new float[res.Length];
        int row = _s * _h, cut = 2;
        Qwen4ExpGatedResidual.GroupRmsNorm(res.AsSpan(0, cut * row), gamma, _s, _h, _eps, chunked.AsSpan(0, cut * row), cut);
        Qwen4ExpGatedResidual.GroupRmsNorm(res.AsSpan(cut * row), gamma, _s, _h, _eps, chunked.AsSpan(cut * row), _t - cut);
        Assert.Equal(whole, chunked);

        var y = Fx.F32("gr.block_out"); var gains = Fx.F32("gr.gains");
        var a = (float[])res.Clone(); Qwen4ExpGatedResidual.Write(a, y, gains, _s, _h, _t);
        var b = (float[])res.Clone();
        Qwen4ExpGatedResidual.Write(b.AsSpan(0, cut * row), y.AsSpan(0, cut * _h), gains.AsSpan(0, cut * _s), _s, _h, cut);
        Qwen4ExpGatedResidual.Write(b.AsSpan(cut * row), y.AsSpan(cut * _h), gains.AsSpan(cut * _s), _s, _h, _t - cut);
        Assert.Equal(a, b);
    }

    [Fact]
    public void Broadcast_RepeatsEmbeddingIntoEveryStream()
    {
        var emb = Enumerable.Range(0, _t * _h).Select(i => (float)i).ToArray();
        var r = new float[_t * _s * _h];
        Qwen4ExpGatedResidual.Broadcast(emb, _s, _h, r, _t);
        for (int t = 0; t < _t; t++)
        for (int s = 0; s < _s; s++)
        for (int i = 0; i < _h; i++)
            Assert.Equal(emb[t * _h + i], r[t * _s * _h + s * _h + i]);
    }

    [Fact]
    public void Validation_RejectsShortBuffers()
    {
        Assert.Throws<ArgumentException>(() =>
            Qwen4ExpGatedResidual.GroupRmsNorm(new float[10], new float[_s * _h], _s, _h, _eps, new float[_s * _h], 1));
        Assert.Throws<ArgumentException>(() =>
            Qwen4ExpGatedResidual.Write(new float[_s * _h], new float[_h], new float[1], _s, _h, 1));
    }
}
